'use strict'
// A CommonJS table whose FIRST value is a member expression: Node's lexer
// stops there and sees no names; Bun evaluates and exposes every key.
const props = { defaults: { registry: 'https://registry.npmjs.org/' } }
const definitions = { registry: { type: 'url' }, loglevel: { type: 'string' } }
const flatten = (obj) => Object.keys(obj).sort().join('|')
exports.extra = 'via exports'
module.exports = {
  defaults: props.defaults,
  definitions,
  flatten,
  shorthands: { v: ['--version'] },
  extra: exports.extra,
}
